CREATE TYPE efficiency_class AS ENUM ('Excellent Efficiency', 'Good Efficiency', 'Average Efficiency', 'Poor Efficiency');
CREATE OR REPLACE FUNCTION classify_battery_efficiency()
RETURNS SETOF efficiency_class
AS $$
BEGIN
    RETURN QUERY SELECT CASE WHEN (ts.battlifeh * ts.battcapmah)::NUMERIC / (d.pwractmw * 10) > 7.5 THEN 'Excellent Efficiency'::efficiency_class
                WHEN (ts.battlifeh * ts.battcapmah)::NUMERIC / (d.pwractmw * 10) >= 5.0 THEN 'Good Efficiency'::efficiency_class
                WHEN (ts.battlifeh * ts.battcapmah)::NUMERIC / (d.pwractmw * 10) >= 2.5 THEN 'Average Efficiency'::efficiency_class
                ELSE 'Poor Efficiency'::efficiency_class END
    FROM deviceidentity d JOIN testsessions ts ON d.devsessionref = ts.sessionregistry
    WHERE d.conntype IN ('Wireless 2.4GHz', 'Bluetooth');
END;
$$ LANGUAGE plpgsql;
